class IndexedList {
  private a: number[] = [];

  get(index: number): number {
    return index < this.a.length ? this.a[index] : -1;
  }

  addAtHead(val: number): void {
    this.a.unshift(val);
  }

  addAtTail(val: number): void {
    this.a.push(val);
  }

  addAtIndex(index: number, val: number): void {
    if (index <= this.a.length) this.a.splice(index, 0, val);
  }

  deleteAtIndex(index: number): void {
    if (index < this.a.length) this.a.splice(index, 1);
  }
}

